public class ArrayMaximum {
    public static void main(String[] args) {
        int[] numbers = {12, 45, 3, 89, 27, 56};
        int largest = numbers[0];

        for (int n : numbers) {
            if (n > largest) {
                largest = n;
            }
        }

        System.out.println("Largest number: " + largest);
    }
}
